// .NET C# -- Azure SDK for Blob Storage
using Azure.Storage.Blobs;
using Azure.Identity;

var client = new BlobServiceClient(
    new Uri("https://satishpipeline.blob.core.windows.net"),
    new DefaultAzureCredential());

var container = client.GetBlobContainerClient("orders-raw");
await using var stream = File.OpenRead("C:/data/orders.csv");
await container.GetBlobClient("2024/01/orders.csv").UploadAsync(stream, overwrite: true);

await foreach (var blob in container.GetBlobsAsync(prefix: "processed/2024/"))
    Console.WriteLine($"{blob.Name} ({blob.Properties.ContentLength:N0} bytes)");

